use vstd::prelude::*;

verus! {

/// Given a 3×3 matrix of characters in `lines`,
/// return a length‐4 vector consisting of the main diagonal
/// characters followed by a newline `'\n'`.
fn solve(lines: Vec<Vec<char>>) -> Vec<char>
    // We require exactly 3 rows …
    requires
        lines.view().len() == 3,
    // … and each row has length 3
        lines.view()[0].view().len() == 3,
        lines.view()[1].view().len() == 3,
        lines.view()[2].view().len() == 3,
    // The result must be length 4 and pick out exactly
    // the three diagonal entries plus `'\n'`.
    ensures |res: Vec<char>| 
        res.view().len() == 4 &&
        res.view()[0] == lines.view()[0].view()[0] &&
        res.view()[1] == lines.view()[1].view()[1] &&
        res.view()[2] == lines.view()[2].view()[2] &&
        res.view()[3] == '\n',
{
    // Build up the answer
    let mut res: Vec<char> = Vec::new();
    // Push in the (0,0), (1,1), (2,2) entries
    res.push(lines[0][0]);
    res.push(lines[1][1]);
    res.push(lines[2][2]);
    // Finally push the newline
    res.push('\n');
    res
}

} // verus!

fn main() {
    // Example usage
    let m: Vec<Vec<char>> = vec![
        vec!['a','b','c'],
        vec!['d','x','f'],
        vec!['g','h','z'],
    ];
    let diag = solve(m);
    // `diag` is now ['a','x','z','\n']
}